'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);

const n = Number(input[0]);
const k = BigInt(input[1]);
const MOD = 998244353n;

if (k >= BigInt(n)) {
    console.log('0');
    process.exit(0);
}

function power(base, exponent) {
    let result = 1n;
    let value = BigInt(base) % MOD;

    while (exponent > 0) {
        if (exponent % 2 === 1) {
            result = result * value % MOD;
        }
        value = value * value % MOD;
        exponent = Math.floor(exponent / 2);
    }

    return result;
}

const c = n - Number(k);
const factorial = new Array(n + 1);
const inverseFactorial = new Array(n + 1);

factorial[0] = 1n;
for (let i = 1; i <= n; i++) {
    factorial[i] = factorial[i - 1] * BigInt(i) % MOD;
}

inverseFactorial[n] = power(factorial[n], Number(MOD - 2n));
for (let i = n; i > 0; i--) {
    inverseFactorial[i - 1] = inverseFactorial[i] * BigInt(i) % MOD;
}

function choose(total, selected) {
    return factorial[total]
        * inverseFactorial[selected] % MOD
        * inverseFactorial[total - selected] % MOD;
}

let answer = 0n;

for (let a = 1; a <= c; a++) {
    const value = power(a, n) * choose(c, a) % MOD;
    answer += (c - a) % 2 === 0 ? value : -value;
}

answer %= MOD;
if (answer < 0n) {
    answer += MOD;
}

answer = answer * choose(n, c) % MOD;

if (k > 0n) {
    answer = answer * 2n % MOD;
}

console.log(answer.toString());

